    QCOMPARE(persistentValue.row(), initialValueRow);
    QCOMPARE(editor->text(), draft);
    QVERIFY(editor->isModified());
    QVERIFY(editor->isUndoAvailable());
    QTRY_VERIFY(editor->hasFocus());
